const SCHEMA = {"type": "object", "properties": {"category": {"type": "string", "enum": ["product_support", "sales_lead", "recruiter", "newsletter", "other"]}, "confidence": {"type": "number"}, "reason": {"type": "string"}}, "required": ["category", "confidence", "reason"]};
const SYSTEM = "You are an email triage assistant. Read the sender, subject, and preview, then classify the email into exactly one category:\n- product_support: help requests, questions, bugs, or issues about a product or service, usually from customers.\n- sales_lead: inbound prospects or sales inquiries, someone interested in hiring or buying services.\n- recruiter: recruiter outreach, job opportunities, interview requests, or a hiring manager about a role.\n- newsletter: bulk marketing mail only, such as newsletters, product announcements, and digests.\n- other: everything else, including invoices, receipts, payment or account notifications, verification codes, and personal mail.\nImportant: transactional and account emails such as invoices, receipts, and verification codes are NOT newsletters. When unsure between newsletter and other for a transactional email, choose other. Pick the single best category. Return the category, a confidence from 0 to 1, and a short reason.";

// Six fake, generic emails. No real people, addresses, or data. All domains are .example.
const inbox = [
  { id: 'MSG-1', from: 'maria@acme-clients.example', subject: 'Cannot sign in after the latest update', preview: 'Since this morning my whole team is locked out of the dashboard and we have a deadline today.' },
  { id: 'MSG-2', from: 'devon@northwind.example', subject: 'Interested in your automation services', preview: 'We are a 40 person team and want to automate our onboarding. Do you take on new clients this quarter?' },
  { id: 'MSG-3', from: 'talent@brightpath.example', subject: 'Senior Automation Engineer opportunity', preview: 'I came across your profile and think you would be a strong fit for a role with one of our clients.' },
  { id: 'MSG-4', from: 'news@devweekly.example', subject: 'This week in automation: 12 tools to try', preview: 'Your weekly digest of the best automation reads, tools, and tutorials, hand picked for you.' },
  { id: 'MSG-5', from: 'billing@cloudhost.example', subject: 'Your invoice is available', preview: 'Invoice 4821 for your monthly plan is ready to view in your account. No action is needed.' },
  { id: 'MSG-6', from: 'sam@personalmail.example', subject: 'Photos from the weekend', preview: 'Hey, sending over the pictures from Saturday. It was so good to see you and the kids, let us not wait so long next time.' }
];

return inbox.map(e => ({ json: {
  emailId: e.id, from: e.from, subject: e.subject, preview: e.preview,
  ollamaBody: {
    model: 'qwen3:8b', stream: false, think: false, options: { temperature: 0.1 },
    messages: [
      { role: 'system', content: SYSTEM },
      { role: 'user', content: ('From: ' + e.from + '. Subject: ' + e.subject + '. Preview: ' + e.preview) }
    ],
    format: SCHEMA
  }
}}));

const emails = $('Generate sample inbox').all();
// category -> Gmail label name. 'other' means leave the message in the inbox, untouched.
const targets = { product_support: 'Product Support', sales_lead: 'Sales Leads', recruiter: 'Recruiters', newsletter: 'Newsletters', other: null };
return $input.all().map((item, i) => {
  let ai = {};
  try { ai = JSON.parse(item.json.message.content); }
  catch (e) { ai = { category: 'other', confidence: 0, reason: 'parse_failed' }; }
  const e = emails[i].json;
  let category = String(ai.category || 'other');
  const conf = Number(ai.confidence || 0);
  const subject = e.subject || '';
  // Guardrail 1: transactional or account mail is never a newsletter, so it is never auto marked read.
  if (category === 'newsletter' && /(invoice|receipt|payment|purchase|verification code|sign in|password|statement|order number)/i.test(subject)) category = 'other';
  // Guardrail 2: low confidence falls back to a safe bucket for a human to review.
  if (conf < 0.5) category = 'other';
  const labelName = targets[category] || null;
  const wouldLabel = !!labelName;
  const wouldMarkRead = category === 'newsletter';
  let action = 'left in inbox';
  if (wouldLabel && wouldMarkRead) action = 'label + mark read';
  else if (wouldLabel) action = 'label';
  return { json: {
    emailId: e.emailId, from: e.from, subject: e.subject,
    category, confidence: conf, reason: String(ai.reason || ''),
    labelName: labelName || '(none)', wouldLabel, wouldMarkRead, action
  }};
});

const rows = $('Merge routes').all().map(i => i.json);
const byCategory = {};
let labeled = 0, markedRead = 0;
for (const r of rows) {
  byCategory[r.category] = (byCategory[r.category] || 0) + 1;
  if (r.wouldLabel) labeled++;
  if (r.wouldMarkRead) markedRead++;
}
const fmt = Object.entries(byCategory).map(([k, v]) => k + '=' + v).join(', ');
const digest = 'Triaged ' + rows.length + ' emails. Would label ' + labeled + ', would mark read ' + markedRead + '. By category [' + fmt + '].';
return [{ json: { total_emails: rows.length, would_label: labeled, would_mark_read: markedRead, by_category: byCategory, digest } }];
